<script setup lang="ts">
import { ref,onMounted,computed } from 'vue'
import { useRouter } from 'vue-router'
import { Repeat2,Check,CheckCheck,ArrowUpRight,Filter } from 'lucide-vue-next'
import { api,patch,post } from '../api'
import MathText from '../components/MathText.vue'
import EmptyState from '../components/EmptyState.vue'
import Modal from '../components/Modal.vue'
const router=useRouter(),mistakes=ref<any[]>([]),students=ref<any[]>([]),student=ref(''),filter=ref('pending'),selected=ref<string[]>([]),error=ref(''),show=ref(false),busy=ref(false),mode=ref('original'),title=ref('错题巩固 · 专项练习')
const filtered=computed(()=>mistakes.value.filter(m=>(!student.value||m.student===student.value)&&(filter.value==='all'||(filter.value==='mastered'?m.mastered&&m.active:m.active&&!m.mastered))))
async function load(){try{[mistakes.value,students.value]=await Promise.all([api('mistakes/'),api('students/')])}catch(e:any){error.value=e.message}}
onMounted(load)
async function master(m:any){try{await patch(`mistakes/${m.id}/`,{mastered:!m.mastered});await load()}catch(e:any){error.value=e.message}}
async function practice(){busy.value=true;try{const result=await post('mistakes/practice/',{ids:selected.value,mode:mode.value,title:title.value});show.value=false;await router.push('/papers/'+result.id)}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><p class="eyebrow">LEARNING LOOP</p><h1>从“做错”，走向“会做”<span class="heading-dot">.</span></h1><p class="subtitle">保留每一次作答，用复练验证真正的进步。</p></div><button class="button primary" :disabled="!selected.length" @click="show=true"><Repeat2 :size="17"/>生成针对练习（{{selected.length}}）</button></div><div v-if="error" class="notice danger">{{error}}</div><div class="toolbar"><select v-model="student" aria-label="筛选学生" @change="selected=[]"><option value="">全部学生</option><option v-for="s in students" :value="s.id">{{s.name}}</option></select><div class="tabs compact"><button v-for="(label,key) in {pending:'待巩固',mastered:'已确认掌握',all:'全部历史'}" :class="{active:filter===key}" @click="filter=String(key)">{{label}}</button></div><span class="muted small">{{filtered.length}} 条记录</span></div>
 <article v-for="m in filtered" :key="m.id" class="question-card mistake-card"><header class="question-top"><div class="inline wrap"><input v-if="m.active" v-model="selected" type="checkbox" :value="m.id" :aria-label="'选择'+m.student_name+'的错题'"/><strong>{{m.student_name}}</strong><span class="muted small">{{m.test_date}}</span><span class="tag" :class="!m.active?'subtle':m.mastered?'green':'amber'">{{!m.active?'改分后已移出':m.mastered?'已确认掌握':'待巩固'}}</span></div><span class="grade-score">{{m.attempt.final_score}}<small> / {{m.attempt.item.max_score}}</small></span></header><MathText :text="m.attempt.item.snapshot.stem"/><div class="tags"><span v-for="tag in m.attempt.item.snapshot.tags" class="tag subtle">{{tag}}</span></div><div class="grading-columns"><div class="student-answer"><span class="mini-label">当次学生作答</span><MathText :text="m.attempt.student_answer||'空白作答'"/></div><div class="reference-box"><span class="mini-label">参考答案</span><MathText :text="m.attempt.item.snapshot.answer"/></div></div><p class="muted small">{{m.attempt.feedback||'暂无失分评语'}}</p><div v-if="m.followups?.length" class="followup-list"><span class="mini-label">后续复练证据</span><RouterLink v-for="f in m.followups" :key="f.id" :to="'/grading/'+f.submission" class="followup-row"><span>{{f.date}} · {{f.score===null?'待复核':f.score+' / '+f.maximum+' 分'}}</span><ArrowUpRight :size="14"/></RouterLink></div><footer class="question-actions"><RouterLink :to="'/grading/'+m.attempt.submission" class="text-button">查看原始测试<ArrowUpRight :size="15"/></RouterLink><button v-if="m.active" class="button secondary small" @click="master(m)"><Check :size="15"/>{{m.mastered?'恢复待巩固':'教师确认已掌握'}}</button></footer></article><EmptyState v-if="!filtered.length" title="这里记录需要再走一步的题目" text="完成评分后，失分题会自动进入学生错题档案。"/>
 <Modal v-if="show" title="生成学生专属练习" @close="show=false"><form @submit.prevent="practice"><div v-if="error" class="notice danger">{{error}}</div><label>练习名称<input v-model="title" required/></label><label>复练方式<select v-model="mode"><option value="original">原题重做（使用原测试题目版本）</option><option value="similar">同类题迁移（同知识点、相近难度）</option></select></label><p class="helper">已选择 {{selected.length}} 道错题。请只选择同一学生的错题；缺少已审核同类题时会提示补充题库。</p><button class="button primary full" :disabled="busy">{{busy?'生成中…':'生成并保留复练关联'}}</button></form></Modal>
</template>
